import{z as l,x as s,o as e,c as d,q as B,j as n,D as E,d as r,s as A,S as i,b as t}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"组合整合：约束与加权","description":"","frontmatter":{"title":"组合整合：约束与加权","date":"2026-09-18T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/portfolio-integration-cap.md","filePath":"quant/portfolio-integration-cap.md","lastUpdated":1791413859000}'),p={name:"quant/portfolio-integration-cap.md"};function m(D,a,C,h,u,F){const o=s("Mermaid");return e(),d("div",null,[a[2]||(a[2]=B('<h1 id="组合整合-约束与加权" tabindex="-1">组合整合：约束与加权 <a class="header-anchor" href="#组合整合-约束与加权" aria-label="Permalink to &quot;组合整合：约束与加权&quot;">​</a></h1><div class="epigraph"><p>信号只有变成权重才能赚钱；从 IC 到权重的每一步——加权、中性化、约束——都在决定信息率还剩多少交到账上。</p><footer>—— 据 Grinold and Kahn, Active Portfolio Management；Markowitz, 1952 整理</footer></div><p><a href="/quant/multitest-discipline-cap">上一课</a>把多重检验纪律落回现场：这次研究实际动用了哪几件工具——CSCV/PBO 管选择规则的质量、DSR 管选择后的缩水、Romano–Wolf 管家族显著性——怎么统一报告，以及如何不让纪律沦为盖章仪式；它留下的缺口是：信号作为独立下注成立，不等于能进组合。通过检验的信号仍只是横截面上的一个得分列。本单元从信号走向实盘，第一站把得分列变成目标权重；难点不在加权公式，而在与既有持仓的相关、约束集的形状、加权方式与估计误差的匹配。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>信号通过检验后最常见两种错误。其一，另开账本：新信号单独成组合，旧的照旧，两条曲线各自好看，风险上却在同一些名字上叠了双倍杠杆。整合先于加权：把既有组合收益对新信号回归看残差，增量集中在旧组合已超配的行业里时，边际贡献趋近于零。其二，全仓替换：清掉旧组合全押新信号，把分散性一次扔掉。正确的问题永远是「配多少增量、与旧持仓按什么比例混合」。</p><p><span class="marginnote">「同一些名字上叠了双倍杠杆」可以用拼桌点菜来类比：两桌人各自点了半桌菜，合起来可能有三份红烧肉——两份账单各自看都正常，合吃时风险敞口早超了。对新信号回归取残差，就是先问「新菜单里有多少道是旧菜单已经点过的」，只把没点过的算作增量。</span></p><h3 id="三种加权-三种估计误差" tabindex="-1">三种加权，三种估计误差 <a class="header-anchor" href="#三种加权-三种估计误差" aria-label="Permalink to &quot;三种加权，三种估计误差&quot;">​</a></h3><p>等权按得分排序取头尾分位、组内等名义：不吃 \\(\\mu\\) 与 \\(\\Sigma\\) 的点估计，对估计误差免疫、可审计；代价是把同样的仓位花在高信心与低信心的名字上。优化器把得分当预期收益代理、配收缩协方差解均值–方差问题（Markowitz 的框架），理论上最有效，实际在放大估计误差：输入的小扰动给出剧烈变动的权重与爆炸的换手。风险平价与风险预算只吃波动结构不吃 \\(\\mu\\)，得分只用于在预算上倾斜，介于两者之间。选择标准是哪种与你估计得动的东西匹配。</p><p><span class="marginnote">约束的代价有直接度量：目标权重与信号得分的截面相关，叫转移系数。同一信号在多空中性加行业中性下，转移系数可以比无约束低一半——先量这个数再争论信号好坏；系数接近零说明方向被约束集吃掉。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>流水线固定四步。<strong>正交化</strong>：新信号对既有持仓暴露回归取残差，后续一切在残差上做。<strong>选加权</strong>：按上节标准定等权、优化器或预算倾斜；优化器必须配协方差收缩与换手惩罚，否则再平衡换手会提前兑现下一课的成本折扣。<strong>写显式约束</strong>：现金比例、单名上限、行业与风格中性带、杠杆上限全部进优化器，而不是事后修剪。<strong>容量封顶</strong>：每个名字的目标仓位除以 ADV 得参与率，超阈值者削减——阈值由<a href="/quant/strategy-capacity-decay">策略容量与冲击衰减</a>的 \\(\\mu_{\\mathrm{net}}(A)\\) 曲线给出；单策略杠杆上界见<a href="/quant/fractional-kelly-bound">分数 Kelly 的边界</a>，与组合约束取更紧的一个。若约束砍掉的恰是信号最强的一段，先改宇宙或信号表达，而不是让优化器沉默绕行。</p><p><span class="marginnote">数字实例（容量封顶）：某名字 20 日 ADV 为 2000 万股，目标仓位 40 万股，参与率 = 40 ÷ 2000 = 2%；阈值定 5% 就放行，超了就削减。注意 ADV 是 20 日平均——平静市够用，恐慌日成交量可能腰斩，同一笔仓位真实参与率当场翻倍，所以封顶口径要按压力期收紧，不能按平均日。</span></p>',12)),(e(),n(i,null,{default:E(()=>[A(o,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20SIG%5B%22%E6%96%B0%E4%BF%A1%E5%8F%B7%E5%BE%97%E5%88%86%22%5D%20--%3E%20RES%5B%22%E5%AF%B9%E6%97%A2%E6%9C%89%E6%9A%B4%E9%9C%B2%E5%9B%9E%E5%BD%92%E5%8F%96%E6%AE%8B%E5%B7%AE%22%5D%0A%20%20OLD%5B%22%E6%97%A2%E6%9C%89%E7%BB%84%E5%90%88%E4%B8%8E%E6%9A%B4%E9%9C%B2%22%5D%20--%3E%20RES%0A%20%20RES%20--%3E%20W%7B%22%E5%8A%A0%E6%9D%83%E6%96%B9%E5%BC%8F%22%7D%0A%20%20W%20--%3E%7C%E7%AD%89%E6%9D%83%7C%20EW%5B%22%E5%A4%B4%E5%B0%BE%E5%88%86%E4%BD%8D%E7%AD%89%E5%90%8D%E4%B9%89%22%5D%0A%20%20W%20--%3E%7C%E5%9D%87%E5%80%BC%E6%96%B9%E5%B7%AE%7C%20OPT%5B%22%E6%94%B6%E7%BC%A9%E5%8D%8F%E6%96%B9%E5%B7%AE%2B%E6%8D%A2%E6%89%8B%E6%83%A9%E7%BD%9A%22%5D%0A%20%20W%20--%3E%7C%E9%A3%8E%E9%99%A9%E9%A2%84%E7%AE%97%7C%20RP%5B%22%E9%A2%84%E7%AE%97%E5%80%BE%E6%96%9C%22%5D%0A%20%20EW%20--%3E%20CON%5B%22%E6%98%BE%E5%BC%8F%E7%BA%A6%E6%9D%9F%EF%BC%9A%E7%8E%B0%E9%87%91%2F%E8%A1%8C%E4%B8%9A%2F%E5%8D%95%E5%90%8D%2F%E6%9D%A0%E6%9D%86%22%5D%0A%20%20OPT%20--%3E%20CON%0A%20%20RP%20--%3E%20CON%0A%20%20CON%20--%3E%20CAP%5B%22%E5%8F%82%E4%B8%8E%E7%8E%87%E4%B8%8E%E5%AE%B9%E9%87%8F%E5%B0%81%E9%A1%B6%22%5D%0A%20%20CAP%20--%3E%20TGT%5B%22%E7%9B%AE%E6%A0%87%E6%AF%9B%E6%9D%83%E9%87%8D%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=t("h2",{id:"机制",tabindex:"-1"},[r("机制 "),t("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=t("p",null,"Grinold 的分解 \\(\\mathrm{IR}\\approx\\mathrm{IC}\\cdot\\sqrt{\\mathrm{BR}}\\) 说明了约束怎么吃掉信息率：行业中性把有效下注数从 \\(N\\) 压到行业内可对的名子对数，转移系数 \\(\\rho\\) 再乘一次。约束组合的期望 IR 是无约束的 \\(\\rho\\sqrt{\\mathrm{BR}'/\\mathrm{BR}}\\) 倍，多约束是连乘不是加法——这是「约束看着温和、IR 掉得快」的机制。与既有持仓相关的机制是边际贡献递减：已有暴露花掉了风险预算，新信号只在与现有暴露正交的那部分上产生增量。",-1)),a[5]||(a[5]=t("p",null,"约束吃 IR 是一段一段连乘的过程：",-1)),(e(),n(i,null,{default:E(()=>[A(o,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20LR%0A%20%20S%5B%22%E4%BF%A1%E5%8F%B7%EF%BC%9AIC%20%E5%9B%BA%E5%AE%9A%22%5D%20--%3E%20U%5B%22%E6%97%A0%E7%BA%A6%E6%9D%9F%EF%BC%9AIR%20%E2%89%88%20IC%C2%B7%E2%88%9ABR%22%5D%0A%20%20U%20--%3E%20N%5B%22%E8%A1%8C%E4%B8%9A%E4%B8%AD%E6%80%A7%E5%8E%8B%20BR%EF%BC%9A%E5%8F%AF%E4%B8%8B%E7%9A%84%E6%B3%A8%E5%8F%98%E5%B0%91%22%5D%0A%20%20N%20--%3E%20R%5B%22%E8%BD%AC%E7%A7%BB%E7%B3%BB%E6%95%B0%20%CF%81%EF%BC%9A%E6%9D%83%E9%87%8D%E5%81%8F%E7%A6%BB%E5%BE%97%E5%88%86%22%5D%0A%20%20R%20--%3E%20F%5B%22%E5%88%B0%E6%89%8B%20IR%20%3D%20%CF%81%C2%B7%E2%88%9A(BR%E2%80%B2%2FBR)%20%E5%80%8D%22%5D%0A%20%20F%20--%3E%20M%7B%22%E5%86%8D%E5%8A%A0%E4%B8%80%E6%9D%A1%E7%BA%A6%E6%9D%9F%EF%BC%9F%22%7D%0A%20%20M%20--%3E%7C%22%E6%98%AF%22%7C%20N%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[r(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=B('<p><span class="marginnote">「毛权重」指还没扣交易成本、没叠风险约束前的目标仓位，像商品的标价——离你实际支付的到手价还远。初学者容易以为优化器吐出权重就万事大吉，实际上后面还有成本、风险叠加、上线台阶三道折扣，每一道都可能把正的净 IR 翻成负数，翻案要等下一课的数字才算数。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>优化器解只在输入邻域内可信：协方差误差经特征向量放大，最不稳的方向上权重最激进。等权也不免费：信号最强的常是流动性最差的名字，等权把仓位精准配到最难执行处——这是下一课成本预测接手的缺口。容量封顶用的 ADV 随体制变动，平静期的参与率在压力期翻倍超标。最后，本课权重仍是毛的：成本、风险叠加、上线台阶都可能把这条信号的经济性重新翻案。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>整合先于加权：信号价值以对既有组合的增量度量，正交化取残差是第一步。</li><li>加权要与估计误差匹配：等权免疫输入误差但浪费信心差异；优化器放大误差。</li><li>约束显式写进优化器，用转移系数度量代价；约束对 IR 的侵蚀是连乘。</li><li>容量封顶由参与率与 \\(\\mu_{\\mathrm{net}}(A)\\) 给出，与单策略杠杆上界取更紧的一个。</li><li>毛权重之后还有成本、风险、上线三道折扣，任何一层都可能翻案。</li><li>出处：Grinold and Kahn, <em>Active Portfolio Management</em>；Markowitz, <em>JF</em>, 1952。</li></ul>',5))])}const R=l(p,[["render",m]]);export{f as __pageData,R as default};
